css:
:host{
  --navy:#1E2A8A; --navy-d:#16216B; --navy-2:#2A379E; --indigo-50:#EEF2FF; --indigo-700:#3730A3;
  --orange:#FF8C1A; --orange-d:#C2410C; --orange-dd:#9A3412; --amber:#F59E0B; --orange-50:#FFF4E5;
  --teal:#0EA5B7; --teal-d:#0E7490; --teal-50:#ECFEFF;
  --ink:#0F172A; --muted:#475569; --line:#E2E8F0; --bg:#F8FAFC; --card:#FFFFFF;
  --sans:'Plus Jakarta Sans',-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
  --serif:'Newsreader',Georgia,Cambria,'Times New Roman',serif;
  --mono:'JetBrains Mono',ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;
  --grad:linear-gradient(105deg,#1E2A8A 0%,#1E2A8A 55%,#C2410C 80%,#FF8C1A 100%);
  --sat:env(safe-area-inset-top,0px); --sar:env(safe-area-inset-right,0px); --sab:env(safe-area-inset-bottom,0px); --sal:env(safe-area-inset-left,0px);
}
*{box-sizing:border-box}
@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation:none!important;transition:none!important}}
.rsm-root{margin:0;font-family:var(--sans);font-size:16px;line-height:1.55;color:var(--ink);background-color:var(--bg);
  background-image:radial-gradient(#CBD5E1 1.35px,transparent 1.35px);background-size:22px 22px;-webkit-font-smoothing:antialiased}
::selection{background:#FEF08A;color:#854D0E}
button,input{font:inherit;color:inherit}
button:focus-visible,a:focus-visible,input:focus-visible,summary:focus-visible{outline:3px solid var(--amber);outline-offset:2px}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.skip{position:absolute;left:-999px;top:0;background:#fff;color:var(--navy);padding:12px 16px;z-index:100;border-radius:0 0 8px 0;font-weight:700}
.skip:focus{left:0}
sub,sup{font-size:.8em;line-height:0}
.ar{width:1.15em;height:1.15em;vertical-align:-.22em;color:var(--orange-d);display:inline-block;margin:0 .1em}
.frac sup,.frac sub{font-size:.75em}

/* header: exact site gradient + logo treatment (scaled uniformly) */
.top{background:var(--grad);color:#fff;padding-top:var(--sat);box-shadow:0 6px 16px rgba(15,23,42,.25);position:relative;z-index:30}
.top-in{display:flex;align-items:center;justify-content:space-between;gap:12px;max-width:1440px;margin:0 auto;padding:10px calc(16px + var(--sar)) 10px calc(16px + var(--sal))}
.logo{--u:24px;line-height:1;user-select:none;flex:none}
.lg-w{font-weight:800;font-style:italic;text-transform:uppercase;line-height:.95;letter-spacing:-.025em;font-size:var(--u)}
.lg-w>div{-webkit-text-stroke:calc(var(--u)/16) #fff;font-size:var(--u)}
.lg-r{color:#1E2A8A}.lg-s{color:#FF8C1A}.lg-p{color:#1E2A8A;font-style:normal}
.lg-pill{margin-top:calc(var(--u)/16*4);display:inline-block;border-radius:9999px;background:#1E2A8A;color:#fff;padding:calc(var(--u)/16*3) calc(var(--u)/16*8);font-size:calc(var(--u)/16*8);font-weight:800;letter-spacing:.05em}
@media (min-width:900px){.logo{--u:32px}}

.btn{min-height:44px;min-width:44px;padding:8px 16px;border-radius:12px;font-weight:700;font-size:15px;cursor:pointer;border:2px solid transparent;display:inline-flex;align-items:center;justify-content:center;gap:8px;line-height:1.2}
.btn.solid{background:var(--navy);color:#fff;border-color:#fff}
.btn.solid:hover{background:var(--navy-d)}
.btn.ghost{background:#fff;color:var(--navy);border-color:var(--navy)}
.btn.ghost:hover{background:var(--indigo-50)}
.top .btn.solid{background:var(--navy-d);white-space:nowrap}

/* layout */
.shell{max-width:1440px;margin:0 auto;display:grid;grid-template-columns:272px minmax(0,1fr);gap:32px;padding:24px calc(20px + var(--sar)) calc(40px + var(--sab)) calc(20px + var(--sal))}
main{min-width:0;max-width:1100px}
.side{position:sticky;top:16px;align-self:start;max-height:calc(100vh - 32px);overflow:auto;background:#fff;border:1px solid var(--line);border-radius:16px;padding:12px;box-shadow:0 1px 3px rgba(15,23,42,.06)}
.side-t{margin:4px 8px 8px;font-family:var(--mono);font-size:14px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--muted)}
.side ul{list-style:none;margin:0;padding:0;display:grid;gap:2px}
.side a,.chipbar a{display:flex;align-items:center;gap:10px;min-height:44px;padding:8px 12px;border-radius:12px;color:var(--ink);text-decoration:none;font-weight:600;font-size:15px;border:2px solid transparent}
.side a svg,.chipbar a svg{width:22px;height:22px;flex:none;color:var(--navy)}
.side a:hover{background:var(--indigo-50)}
.side a.on,.chipbar a.on{background:var(--navy);color:#fff}
.side a.on svg,.chipbar a.on svg{color:var(--orange)}
.chipbar{display:none}
@media (max-width:999px){
  .shell{grid-template-columns:minmax(0,1fr);gap:0;padding-top:12px}
  .side{display:none}
  .chipbar{display:block;position:sticky;top:0;z-index:25;background:rgba(248,250,252,.96);backdrop-filter:blur(6px);border-bottom:1px solid var(--line);padding:6px 0 6px}
  .chipscroll{display:flex;gap:8px;overflow-x:auto;padding:2px calc(16px + var(--sar)) 2px calc(16px + var(--sal));scrollbar-width:none;-webkit-overflow-scrolling:touch}
  .chipscroll::-webkit-scrollbar{display:none}
  .chipbar a{flex:none;white-space:nowrap;background:#fff;border:2px solid var(--line);border-radius:9999px;padding:6px 14px}
  .chipbar a.on{border-color:var(--navy)}
  .sys,.hero{scroll-margin-top:64px}
}
.sys{scroll-margin-top:16px;container:sys/inline-size}

/* hero */
.hero{background:#fff;border:1px solid var(--line);border-radius:20px;padding:28px 28px 24px;box-shadow:0 1px 3px rgba(15,23,42,.06);position:relative;overflow:hidden;margin-bottom:28px}
.hero::before{content:"";position:absolute;left:0;top:0;right:0;height:6px;background:var(--grad)}
.eyebrow{margin:0 0 4px;font-family:var(--mono);font-size:14px;font-weight:700;letter-spacing:.08em;text-transform:uppercase;color:var(--orange-d)}
h1{margin:0 0 10px;font-size:clamp(26px,4.2vw,40px);line-height:1.12;font-weight:800;color:var(--navy);letter-spacing:-.02em}
.lede{margin:0 0 16px;font-family:var(--serif);font-size:19px;line-height:1.6;color:#1e293b;max-width:70ch}
.stats{list-style:none;margin:0 0 18px;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.stats li{background:var(--indigo-50);color:var(--navy);border-radius:9999px;padding:6px 14px;font-weight:600;font-size:15px}
.stats b{font-family:var(--mono);color:var(--navy-d)}
.hero-ctl{display:flex;flex-wrap:wrap;gap:10px}
.hero-ctl .btn.solid{border-color:var(--navy)}

/* system sections */
.sys{margin:0 0 40px}
.sys-h{display:flex;align-items:center;gap:16px;flex-wrap:wrap;background:var(--grad);color:#fff;border-radius:18px 18px 0 0;padding:16px 20px;position:relative}
.sys-ico{width:56px;height:56px;border-radius:16px;background:#fff;color:var(--navy);display:grid;place-items:center;flex:none;box-shadow:0 2px 6px rgba(15,23,42,.25)}
.sys-ico svg{width:32px;height:32px}
.sys-tt{flex:1 1 260px;min-width:0}
.sys-h .eyebrow{color:#fff;margin:0;opacity:1}
.sys-h h2{margin:0;font-size:clamp(22px,3.2vw,30px);line-height:1.15;font-weight:800;color:#fff;letter-spacing:-.01em}
.sys-ctl{display:flex;gap:8px;flex-wrap:wrap}
.sys-ctl .btn{border-color:var(--navy);background:#fff}
.blk{background:#fff;border:1px solid var(--line);border-top:0;padding:20px}
.sys>.blk:last-child{border-radius:0 0 18px 18px;box-shadow:0 1px 3px rgba(15,23,42,.06)}
.blk-t{margin:0 0 14px;font-size:18px;font-weight:800;color:var(--navy);display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 12px}
.blk-t .hint{font-family:var(--sans);font-size:14px;font-weight:500;color:var(--muted)}
@media (max-width:640px){.hero{padding:22px 18px}.blk{padding:16px 14px}.sys-h{padding:14px}.sys-ico{width:48px;height:48px}.lede{font-size:18px}}
@media (max-width:999px){.sys-h{border-radius:16px 16px 0 0}.sys-ctl .btn{flex:1 1 140px}}

/* 5-step flow */
.flow{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:minmax(0,1fr);gap:0}
.fl-li{display:grid;grid-template-columns:minmax(0,1fr);justify-items:stretch}
.fl{display:flex;align-items:flex-start;gap:12px;text-align:left;width:100%;min-height:64px;padding:12px 14px;background:var(--indigo-50);border:2px solid #C7D2FE;border-radius:14px;cursor:pointer;color:var(--ink);font-weight:600;font-size:15px;line-height:1.35}
.fl:hover{border-color:var(--navy);background:#E0E7FF}
.fl-n{flex:none;width:34px;height:34px;border-radius:50%;background:var(--navy);color:#fff;display:grid;place-items:center;font-family:var(--mono);font-weight:700;font-size:16px}
.fl-li.s5 .fl-n{background:var(--orange);color:var(--ink)}
.fl-li.s5 .fl{background:var(--orange-50);border-color:#FDBA74}
.fl-t{padding-top:4px;min-width:0;overflow-wrap:anywhere}
.fl-ar{width:28px;height:28px;color:var(--orange-d);justify-self:center;transform:rotate(90deg);margin:2px 0}
@container sys (min-width:900px){
  .flow{grid-template-columns:repeat(5,minmax(0,1fr));gap:0 4px}
  .fl-li{grid-template-columns:minmax(0,1fr) 22px;position:relative}
  .fl-li:last-child{grid-template-columns:minmax(0,1fr)}
  .fl{flex-direction:column;align-items:flex-start;height:100%;min-height:148px;padding:14px 12px}
  .fl-ar{transform:none;width:24px;height:24px;margin:0;align-self:center;justify-self:center}
}

/* decision trees */
.tree{margin:22px 0 0;padding:16px;border:1px solid var(--line);border-radius:16px;background:linear-gradient(180deg,#fff,#F8FAFC)}
.tree figcaption h4{margin:0;font-size:18px;color:var(--navy);font-weight:800}
.tree figcaption p{margin:2px 0 10px;color:var(--muted);font-size:15px}
.legend{list-style:none;margin:0 0 12px;padding:0;display:flex;flex-wrap:wrap;gap:6px 16px;font-size:14px;font-weight:600;color:var(--ink)}
.legend li{display:flex;align-items:center;gap:6px}
.sw{width:18px;height:18px;border-radius:5px;background:var(--bg);border:2px solid var(--bd);display:inline-block}
.k-root{--bg:#16216B;--bd:#FF8C1A;--fg:#fff}
.k-test{--bg:#fff;--bd:#1E2A8A;--fg:#0F172A}
.k-low{--bg:#CFF4F8;--bd:#0E7490;--fg:#0F172A}
.k-high{--bg:#FFE0BF;--bd:#C2410C;--fg:#0F172A}
.k-norm{--bg:#F1F5F9;--bd:#64748B;--fg:#0F172A}
.k-dx{--bg:#1E2A8A;--bd:#16216B;--fg:#fff}
.k-cat{--bg:#E0E7FF;--bd:#3730A3;--fg:#0F172A}
.k-chip{--bg:#fff;--bd:#94A3B8;--fg:#0F172A}
.tree-svg{display:block;width:100%;height:auto;overflow:visible}
.nd rect{fill:var(--bg);stroke:var(--bd);stroke-width:2.2}
.nd text{fill:var(--fg);font-family:var(--sans);font-weight:700;font-size:15px}
.k-root rect{stroke-width:3.5}
.k-chip text{font-size:14.5px;font-weight:600}
.edge{fill:none;stroke-width:2.6;stroke-linejoin:round}
.e-n{stroke:#475569}.e-low{stroke:#0E7490}.e-high{stroke:#C2410C}.e-dx{stroke:#1E2A8A}
.mk.e-n{fill:#475569}.mk.e-low{fill:#0E7490}.mk.e-high{fill:#C2410C}.mk.e-dx{fill:#1E2A8A}
.vt{display:none}
@container sys (max-width:880px){
  .tree-svg{display:none}
  .vt{display:block}
}
.vt,.vt ul{list-style:none;margin:0;padding:0}
.vt ul{margin:6px 0 0 8px;padding-left:12px;border-left:3px solid #C7D2FE}
.vt li{position:relative;margin:8px 0;display:flex;flex-wrap:wrap;align-items:center;gap:6px}
.vt li.ch{margin-bottom:22px}
.vt li.ch::after{content:"";position:absolute;left:22px;bottom:-16px;width:3px;height:14px;background:#94A3B8;border-radius:2px}
.vt li.ch>.vt-e{flex:none}
.vt li>ul{flex:1 1 100%;margin-top:8px}
.vt-n{display:inline-block;background:var(--bg);color:var(--fg);border:2px solid var(--bd);border-radius:11px;padding:8px 12px;font-weight:700;font-size:15px;line-height:1.3;max-width:100%}
.vt-e{display:inline-block;border:2px solid #94A3B8;border-radius:9999px;padding:4px 10px;font-weight:600;font-size:14px;background:#fff}
.vt-a{font-weight:800;color:var(--orange-d);font-size:20px;line-height:1}

/* cards, rows, chips */
.cards,.subcards{display:grid;gap:14px;margin:0 0 14px;grid-template-columns:minmax(0,1fr)}
.subcards{gap:10px;margin:10px 0 0}
@container sys (min-width:760px){
  .cards.n2,.cards.n3,.subcards.n2,.subcards.n3{grid-template-columns:repeat(2,minmax(0,1fr))}
  .cards.n3,.subcards.n3{grid-template-columns:repeat(3,minmax(0,1fr))}
  .side .subcards.n3{grid-template-columns:minmax(0,1fr)}
}
.card{--ac:var(--navy);--hb:var(--indigo-50);--ht:var(--navy);background:#fff;border:1px solid var(--line);border-left:6px solid var(--ac);border-radius:14px;overflow:hidden;min-width:0}
.card.c1{--ac:var(--teal);--hb:var(--teal-50);--ht:#0B5666}
.card.c2{--ac:var(--orange);--hb:var(--orange-50);--ht:var(--orange-dd)}
.card-h{background:var(--hb);color:var(--ht);font-weight:800;font-size:16px;padding:10px 14px;line-height:1.3}
.card-b{padding:12px 14px;font-size:15.5px}
.card-b>p{margin:0 0 8px}.card-b>*:last-child{margin-bottom:0}
.card.sub{border-radius:12px}.card.sub .card-h{font-size:15px;padding:8px 12px}
.card.it .card-h{font-style:normal}
p.plain,.card-b p{overflow-wrap:anywhere}
.rows{display:grid;gap:8px;margin:0 0 10px}
.rows:last-child,.card-b .rows:last-child{margin-bottom:0}
.row-item p.plain{margin:0;padding:8px 12px;background:#F8FAFC;border-left:4px solid #CBD5E1;border-radius:8px;font-size:15.5px}
.row-item>.rows,.row-item>.cards,.row-item>.subcards{margin:8px 0 0 12px}
.ar-rows{display:grid;gap:8px}
.ar-row{display:grid;grid-template-columns:minmax(0,1fr) 30px minmax(0,1.25fr);gap:6px;align-items:stretch}
.ar-l,.ar-r{padding:8px 12px;border-radius:10px;font-size:15.5px;line-height:1.4;overflow-wrap:anywhere}
.ar-l{background:#F1F5F9;border:1px solid #CBD5E1;font-weight:600}
.ar-r{background:var(--indigo-50);border:1px solid #C7D2FE}
.ar-r b{color:var(--navy);font-weight:800}
.ar-m{display:grid;place-items:center}
.ar-m .ar{width:24px;height:24px;margin:0}
@media (max-width:560px){
  .ar-row{grid-template-columns:30px minmax(0,1fr);gap:4px 6px}
  .ar-l{grid-column:1 / -1}
  .ar-m{grid-row:2}.ar-r{grid-row:2}
}
.chips{list-style:none;margin:0 0 6px;padding:0;display:flex;flex-wrap:wrap;gap:8px}
.chip{display:flex;flex-direction:column;gap:2px;background:#fff;border:2px solid #C7D2FE;border-left:6px solid var(--navy);border-radius:12px;padding:8px 12px;min-width:0;max-width:100%;flex:1 1 220px}
.chip-t{font-weight:800;color:var(--navy);font-size:15.5px;line-height:1.3;overflow-wrap:anywhere}
.chip-n{font-size:15px;color:#1e293b;line-height:1.35;overflow-wrap:anywhere}
.crit{margin:0 0 6px;padding:0;list-style:none;counter-reset:c;display:grid;gap:10px}
.crit li{counter-increment:c;display:flex;gap:12px;align-items:center;background:var(--orange-50);border:2px solid #FDBA74;border-radius:12px;padding:10px 14px;font-size:16px;font-weight:600}
.crit li::before{content:counter(c);flex:none;width:34px;height:34px;border-radius:50%;background:var(--orange);color:var(--ink);display:grid;place-items:center;font-family:var(--mono);font-weight:700}

/* step panels */
.panels{display:grid;gap:10px}
.step{border:2px solid #C7D2FE;border-radius:14px;background:#fff;overflow:hidden}
.step[open]{border-color:var(--navy)}
.step summary{list-style:none;display:flex;align-items:center;gap:12px;min-height:56px;padding:10px 14px;cursor:pointer;font-weight:700;font-size:16px;background:var(--indigo-50);color:var(--ink);-webkit-tap-highlight-color:transparent}
.step summary::-webkit-details-marker{display:none}
.step[open] summary{background:var(--navy);color:#fff}
.st-b{flex:none;font-family:var(--mono);font-size:14px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;background:var(--navy);color:#fff;border-radius:8px;padding:5px 9px}
.step[open] .st-b{background:var(--orange);color:var(--ink)}
.step.s5 .st-b{background:var(--orange);color:var(--ink)}
.st-t{flex:1;min-width:0;line-height:1.3}
.st-c{width:26px;height:26px;flex:none;transition:transform .2s}
.step[open] .st-c{transform:rotate(180deg)}
.st-body{padding:16px 14px 14px;border-top:2px solid var(--navy)}
.st-body>p{margin:0 0 10px;font-size:16px}
.st-body>*:last-child{margin-bottom:0}
.step:target{box-shadow:0 0 0 3px var(--amber)}
.step{scroll-margin-top:72px}
@media (min-width:1000px){.step{scroll-margin-top:16px}}

/* matrices */
.tbl-wrap{overflow-x:auto;margin:0 0 14px;border-radius:12px;border:1px solid var(--line);-webkit-overflow-scrolling:touch}
.matrix{border-collapse:separate;border-spacing:0;width:100%;font-size:15.5px;min-width:520px}
.matrix th,.matrix td{padding:10px 14px;text-align:left;vertical-align:top;border-bottom:1px solid var(--line);line-height:1.4}
.matrix thead th{background:var(--navy);color:#fff;font-weight:800;font-size:15.5px;white-space:nowrap}
.m2 thead th:nth-child(3),.m3 thead th:nth-child(3),.m-oara thead th:nth-child(3),.m-crys thead th:nth-child(3){background:var(--teal-d)}
.matrix thead th b{font-weight:800}
.matrix tbody th{background:#F1F5F9;font-weight:700;color:var(--navy);white-space:nowrap}
.matrix tbody tr:last-child>*{border-bottom:0}
.m2 td:nth-child(2),.m3 td:nth-child(2),.m-oara td:nth-child(2),.m-crys td:nth-child(2){background:var(--orange-50)}
.m2 td:nth-child(3),.m3 td:nth-child(3),.m-oara td:nth-child(3),.m-crys td:nth-child(3){background:var(--teal-50)}
.m5 tbody tr:nth-child(odd) td,.m-iron tbody tr:nth-child(odd) td{background:#FAFBFF}
.m5 tbody th{white-space:normal}
.m-iron tbody th{white-space:normal;background:#fff;color:var(--ink);font-weight:600}
.lv{display:inline-block;border-radius:9999px;padding:2px 12px;font-weight:700}
.lv.low{background:#CFF4F8;color:#0B4A59}.lv.high{background:#FFE0BF;color:var(--orange-dd)}
.na{color:var(--muted);font-weight:700}
.two{display:grid;gap:14px;margin-top:6px}
@container sys (min-width:760px){.two{grid-template-columns:repeat(2,minmax(0,1fr))}}
.side-h{font-weight:800;padding:8px 12px;border-radius:10px;margin-bottom:8px;color:#fff;background:var(--navy);font-size:16px}
.side.nephro .side-h{background:var(--teal-d)}
.casts{display:grid;gap:10px}
.cast-row{display:grid;grid-template-columns:76px minmax(0,1fr) 28px minmax(0,1.3fr);align-items:center;gap:10px;background:#fff;border:1px solid var(--line);border-radius:12px;padding:8px 12px}
.cast{width:76px;height:30px}
.cast-n{font-weight:800;color:var(--navy);font-size:15.5px}
.cast-d{font-size:15.5px}
.cast-d b{color:var(--navy)}
@media (max-width:560px){.cast-row{grid-template-columns:76px minmax(0,1fr);}.cast-row .ar-m{display:none}.cast-d{grid-column:1 / -1;padding-left:2px}}

/* hooks */
.flt{display:flex;align-items:center;gap:10px;background:#fff;border:2px solid #94A3B8;border-radius:12px;padding:0 14px;min-height:48px;max-width:560px}
.flt:focus-within{border-color:var(--navy)}
.flt svg{width:22px;height:22px;color:var(--navy);flex:none}
.flt input{flex:1;min-width:0;border:0;outline:0;background:transparent;font-size:16px;min-height:44px}
.hk-count{margin:8px 2px 12px;color:var(--muted);font-size:14.5px}
.hooks{list-style:none;margin:0;padding:0;display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:10px}
.hook{display:flex;flex-direction:column;gap:4px;background:#fff;border:1px solid var(--line);border-left:6px solid var(--orange);border-radius:12px;padding:10px 14px}
.hk-t{font-weight:800;color:var(--navy);font-size:16px;line-height:1.3}
.hk-d{font-size:15.5px;color:#1e293b;line-height:1.4}
.hook[hidden]{display:none}
.foot{text-align:center;color:var(--muted);font-size:14.5px;border-top:3px solid transparent;border-image:var(--grad) 1;padding-top:16px}
.foot p{margin:2px 0}

/* print */
@page{size:A4 landscape;margin:11mm}
@media print{
  body{background:#fff!important;font-size:12.5px}
  *{-webkit-print-color-adjust:exact;print-color-adjust:exact}
  .skip,.chipbar,.side,.btn,.flt,.hk-count,.hero-ctl,.sys-ctl,.blk-t .hint,.top .btn{display:none!important}
  .top{box-shadow:none}
  .shell{display:block;padding:0}
  main{max-width:none}
  .hero{box-shadow:none;break-inside:avoid}
  .sys{break-before:page;margin:0}
  #sys-1{break-before:auto}
  .sys-h{break-after:avoid}
  .step,.card,.tree,.chip,.ar-row,.cast-row,.hook,.tbl-wrap{break-inside:avoid}
  .step summary{background:var(--indigo-50)!important;color:var(--ink)!important}
  .st-c{display:none}
  .st-b{background:var(--navy)!important;color:#fff!important}
  .tree-svg{display:block!important}.vt{display:none!important}
  .tbl-wrap{overflow:visible}.matrix{min-width:0}
  .hooks{grid-template-columns:repeat(3,minmax(0,1fr))}
  .tree-svg{max-height:150mm;width:auto;max-width:100%;margin:0 auto}
  .hero{padding:14px 20px;margin-bottom:12px}
  .hero p{margin:4px 0}
  .stepper,.flow{break-inside:avoid}
}

.m2 td,.m3 td,.m-oara td,.m-crys td{width:39%}
.m2 tbody th,.m3 tbody th,.m-oara tbody th,.m-crys tbody th{width:22%}

.card-b .ar-row,.subcards .ar-row{grid-template-columns:minmax(0,1fr)}
.card-b .ar-row .ar-m{height:26px}
.card-b .ar-row .ar-m .ar{transform:rotate(90deg)}
.card-b .ar-l,.card-b .ar-r{padding:6px 10px}

/* phone: matrices become stacked cards instead of sideways scroll */
@container sys (max-width:640px){
 .tbl-wrap{overflow:visible;border:0;border-radius:0}
 .matrix{display:block;min-width:0}
 .matrix thead{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0)}
 .matrix tbody{display:grid;gap:10px}
 .matrix tbody tr{display:block;border:1px solid var(--line);border-radius:12px;overflow:hidden;background:#fff}
 .matrix tbody th{display:block;white-space:normal;border-bottom:0;background:var(--navy);color:#fff;font-size:16px}
 .m-iron tbody th{background:var(--navy);color:#fff}
 .matrix tbody td{display:block;border-bottom:1px solid var(--line);padding:8px 14px 10px}
 .matrix tbody td:last-child{border-bottom:0}
 .matrix tbody td::before{content:attr(data-l);display:block;font-weight:800;font-size:14px;letter-spacing:.02em;color:var(--navy);margin-bottom:2px}
 .m2 td:nth-child(3)::before,.m3 td:nth-child(3)::before,.m-oara td:nth-child(3)::before,.m-crys td:nth-child(3)::before{color:var(--teal-d)}
 .m5 tbody td,.m-iron tbody td{background:#fff!important}
 .m2 td,.m3 td,.m-oara td,.m-crys td,.m2 tbody th,.m3 tbody th,.m-oara tbody th,.m-crys tbody th{width:auto}
}

/* ---- in-app adjustments (embedded inside the Rapid Steps shell) ---- */
.rsm-root{min-height:100%}
.side{max-height:calc(100dvh - 140px);top:12px}
.shell{padding-top:16px}
@media (min-width:1000px) and (max-width:1279px){.shell{grid-template-columns:220px minmax(0,1fr);gap:20px}}


:host-context(.dark), :host([data-theme="dark"]), .dark-theme {
  --bg:#09111F; --card:#0F1A2E; --ink:#F1F5F9; --muted:#94A3B8; --line:rgba(255,255,255,0.12);
  --indigo-50:rgba(30,42,138,0.3); --teal-50:rgba(14,165,183,0.2); --orange-50:rgba(255,140,26,0.2);
}
:host-context(.dark) .hero, :host([data-theme="dark"]) .hero, .dark-theme .hero {
  background:#0F1A2E; border-color:rgba(255,255,255,0.12);
}
:host-context(.dark) .side, :host([data-theme="dark"]) .side, .dark-theme .side {
  background:#0F1A2E; border-color:rgba(255,255,255,0.12);
}
:host-context(.dark) .chipbar, :host([data-theme="dark"]) .chipbar, .dark-theme .chipbar {
  background:#09111F; border-color:rgba(255,255,255,0.12);
}
:host-context(.dark) .tree-box, :host([data-theme="dark"]) .tree-box, .dark-theme .tree-box {
  background:#0F1A2E; border-color:rgba(255,255,255,0.12);
}
:host-context(.dark) .st-body, :host([data-theme="dark"]) .st-body, .dark-theme .st-body {
  background:#0F1A2E;
}
:host-context(.dark) .card, :host([data-theme="dark"]) .card, .dark-theme .card {
  background:#0F1A2E; border-color:rgba(255,255,255,0.12);
}
:host-context(.dark) .hook, :host([data-theme="dark"]) .hook, .dark-theme .hook {
  background:#0F1A2E; border-color:rgba(255,255,255,0.12);
}
